<?php
namespace App\Http\Controllers;use App\Models\Setting;use Illuminate\Http\RedirectResponse;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Inertia\Inertia;use Inertia\Response;
class SettingController extends Controller{public function edit():Response{return Inertia::render('Settings/Edit',['settings'=>$this->values()]);}public function update(Request $request):RedirectResponse{$data=$request->validate(['library_name'=>['required','string','max:120'],'institution_name'=>['required','string','max:160'],'contact_email'=>['nullable','email','max:160'],'contact_phone'=>['nullable','string','max:40'],'default_loan_days'=>['required','integer','min:1','max:90'],'max_books_per_loan'=>['required','integer','min:1','max:20'],'scanner_inactivity_seconds'=>['required','integer','min:10','max:180'],'card_validity_months'=>['required','integer','min:1','max:60']]);DB::transaction(function()use($data){foreach($data as $key=>$value)Setting::put($key,$value,str_contains($key,'loan')||str_contains($key,'scanner')||str_contains($key,'card_')?'operations':'general');});return back()->with('success','Paramètres enregistrés et appliqués.');}private function values():array{return['library_name'=>Setting::getValue('library_name','Bibliothèque EDSP'),'institution_name'=>Setting::getValue('institution_name','Université de Mahajanga'),'contact_email'=>Setting::getValue('contact_email',''),'contact_phone'=>Setting::getValue('contact_phone',''),'default_loan_days'=>(int)Setting::getValue('default_loan_days',14),'max_books_per_loan'=>(int)Setting::getValue('max_books_per_loan',5),'scanner_inactivity_seconds'=>(int)Setting::getValue('scanner_inactivity_seconds',40),'card_validity_months'=>(int)Setting::getValue('card_validity_months',12)];}}
